-- GENERATED by `wfj generate` from data/gossip/gossip-08.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0806952737e9ac18"] = { "Grazie, <signore/signorina>, per aver trovato la mia collana! Sei <il/la> migliore!", "." },
  ["080875fa6363fa7a"] = { "Ma la tua vera punizione deve ancora venire.", "." },
  ["08228ab9fe3f2bc0"] = { "Sento la presenza del male che se ne va...", "." },
  ["082e4893cac48c98"] = { "Buliwyf, il maestro d'armi nano proprio qui alla Timberline Arms, insegna armi da pugno, armi da fuoco, asce a una e a due mani e mazze a una e a due mani.\n\nWoo Ping, il maestro d'armi umano al Weller's Arsenal di ⟦Stormwind=Roccavento⟧, insegna balestre, pugnali, spade a una e a due mani, armi in asta e bastoni.\n\n⟦Ilyenia Moonfire=Ilyenia Lunardente⟧, la maestra d'armi elfa della notte, risiede alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧ di Darnassus, dove insegna archi, pugnali, armi da pugno, bastoni e armi da lancio.", "." },
  ["082ed90eb7e4986d"] = { "I tuoi resti in putrefazione serviranno a ME come monito di cosa succede a chi è tanto folle da violare il mio dominio!", "." },
  ["083310fd3f3bd0c9"] = { "Che ti aspetti, amico?\n\nMaywiki tratta solo con druidi e sciamani.", "." },
  ["0838edf39a51c216"] = { "Finalmente sono in libertà! Torno presto a casa, tesoro mio!", "." },
  ["084005154e1c2e6e"] = { "Oh, anche tu pratichi la medicina. Ti insegnerò volentieri tutto ciò che può aiutarti nei tuoi viaggi.", "." },
  ["08408a83deba82a8"] = { "Ahah! Il vecchio e robusto Trollplow ha solo qualche misera cicatrice di battaglia!", "." },
  ["0850413448d81cc8"] = { "Affascinante, questo coincide con le teorie secondo cui Un'Goro era la dimora dei Titani quando abitavano Kalimdor. Forse lo stesso Aman'thul vegliava sulle «Terre degli Dei».", "." },
  ["08569f41a68e40b2"] = { "Sì, <signore/signora>.", "." },
  ["0857aac6a0c5995e"] = { "Dicono che un punto dato in tempo ne salvi... quanti, undici? Ah, non mi ricordo. Detto stupido, comunque.", "." },
  ["08611f453a23493b"] = { "Un'abilità che richiede tempo, ma che dà soddisfazione. Parla con ⟦Astaia=Kirolla⟧ alla Tradesman's Terrace e forse imparerai qualcosa di utile.", "." },
  ["0865b94038b42412"] = { "Salute, {class}. Non ho molto tempo per parlare: uso Ventofreddo come campo base per riposare prima di partire per ⟦Hearthglen=Valsalda⟧. Ho sentito dire che, prima di impazzire, la ⟦Scarlet Crusade=Crociata Scarlatta⟧ aveva al suo servizio un mago che cercava di creare archi e armi da fuoco potenti per i suoi soldati. Non so se ci sia riuscito o no... la Crociata l'ha ucciso prima che uno solo dei suoi prodotti finiti uscisse da lì. Forse l'hanno ucciso per mantenere il segreto... o forse diffidano dell'arcano fino a quel punto.", "." },
  ["0869889bab4b34c2"] = { "Spero che tu mi interrompa per un buon motivo: stavo facendo un lavoro importante.", "." },
  ["08749359af36afe1"] = { "%s è circondato da una barriera di antimagia.", "." },
  ["087752b4db9289c0"] = { "Ehi, Nagmara! Che ne dici di un boccale di Birra dei ⟦Dark Iron=Ferroscuro⟧?", "." },
  ["0879136559eae016"] = { "Non capisco bene...", "." },
  ["087ab206760ea567"] = { "Kel'thuzad fare ⟦Patchwerk=Pezzacarne⟧ suo avatar di guerra!", "." },
  ["088743d70561dff3"] = { "Se hai perso un pezzo della tua armatura zandalari, forse posso aiutarti.", "." },
  ["088ed6c5add107f6"] = { "%s scompare in una nuvola di polvere.", "." },
  ["0899e97b5dd36917"] = { "Ah! Ti prego, se vedi un sopravvissuto del ⟦Darrowshire=Borgo di Darrow⟧, digli che ho riacquistato la libertà!", "." },
  ["089ee93ec7e56ca3"] = { "Ansekhwa, il maestro d'armi tauren, sta sull'altura inferiore di ⟦Thunder Bluff=Picco del Tuono⟧. Lui insegna mazze a una e a due mani, bastoni e armi da fuoco.\n\nArchibald, il maestro d'armi non morto nel ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧, insegna bene balestre, pugnali, spade a una e a due mani e armi in asta.\n\nSayoc, il brutto orco proprio qui, può insegnare archi, pugnali, armi da pugno, asce a una e a due mani e armi da lancio, amico.", "." },
  ["089ef15c926b15c2"] = { "Lady Jaina, può sembrare una richiesta strana... ma ho un giovane pupillo molto timido. Per lui sei un'eroina, e mi ha chiesto di farmi fare il tuo autografo.", "." },
  ["08a68ae51bc11050"] = { "Salve, {name}. Ti interessa la sopravvivenza all'aperto? Nutrirsi della flora e della fauna di queste terre!\n\nPotresti imparare un paio di cose da me, se ti interessa.", "." },
  ["08b34918bd297801"] = { "Fammi sapere quando è il momento migliore per partire. Devi essere i nostri occhi e le nostre orecchie sul fronte.", "." },
  ["08bb13f9df92705f"] = { "Il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sta molto a sud di Kalimdor. Oltre ⟦Thousand Needles=Millepicchi⟧, a Tanaris. Cerca le grandi pietre fluttuanti... segnano l'ingresso del Cratere. Ma fa' attenzione... non è un sentiero facile. I raptor non sono lontani dall'ingresso.", "." },
  ["08c84852d8b96bc0"] = { "Si chiama Tai'jin, e la troverai nella caserma sul lato est di ⟦Razor Hill=Tranciacolle⟧. Ti insegnerà a rispettare gli dei. E assicurati di mostrarle il dovuto rispetto, a tua volta!", "." },
  ["08c9be771521ab46"] = { "BIRRA!", "." },
  ["08cc76c24fc4a8c5"] = { "A ⟦Felwood=Vilbosco⟧ ci sono piante che si possono salvare dalla corruzione applicandovi l'Unguento per Piante Cenariano. So preparare l'unguento con diversi tipi di oggetti; in base alle tue abilità, potresti avere più modi per aiutarmi.\n\nPer il tuo lavoro qui ti servirà anche un Rilevatore Cenariano: è un congegno che ti permette di vedere il marciume e la corruzione della natura che sfuggono all'occhio nudo.", "." },
  ["08ccd3f2d0d5d123"] = { "Nathanos, ho perso la mela marcia. Me ne serve un'altra.", "." },
  ["08cf8e2ebfffb470"] = { "Non dimenticherrrò ciò che hai fatto...\n\nTi prego, lasssciami...", "." },
  ["08d4846256abdaa3"] = { "No... non puoi sederti sulle mie ginocchia.", "." },
  ["08d9e5eea79dd956"] = { "Cos'è una \"matrice dell'essere sotterraneo\"?", "." },
  ["08dd44162f6b80a2"] = { "Per tanto tempo ho vagato nel buio... La corruzione dell'Incubo mi aveva consumato... E ora tu... tutti voi... mi avete salvato. Mi avete liberato dalla sua morsa.", "." },
  ["08ddafe00ec29ced"] = { "Se vuoi migliorare oltre il tuo livello attuale, dovrai trovare Nat Pagle ad ⟦Dustwallow Marsh=Acquemorte⟧.", "." },
  ["08f1a114f5ec496d"] = { "Banca", "." },
  ["08f85f15b045e2e4"] = { "«Malattie magiche», no. «Matrici magiche», no. Ah, eccolo: «Misteri magici».", "." },
  ["08fc1f7fe314d477"] = { "Mi spiace, <ragazzo/ragazza>, non sei ancora all'altezza di imparare da me. Va' da mio figlio Groum: un nuovo apprendista gli farebbe proprio piacere.", "." },
})
